SINA_SMART["physics1-respiration"] = {"lecture":"physics1-respiration","title":"Biophysics of respiration and gas transport","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-respiration:e0","text":"Five processes: ventilation, lung exchange, blood transport, tissue exchange, mitochondrial oxidation.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-respiration:e1","text":"Conduction zone vs respiratory zone.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-respiration:e2","text":"Inspiration active; expiration passive.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-respiration:e3","text":"Gases diffuse down partial pressure gradients.","topic":"Gas exchange","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-respiration:e4","text":"Atmosphere PO₂ 152; alveolus PO₂ ≈ 100, PCO₂ 40; venous PO₂ 40, PCO₂ 47 mmHg.","topic":"Gas exchange","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-respiration:e5","text":"Fick: flux ∝ D·s·S·ΔP / e.","topic":"Gas exchange","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-respiration:e6","text":"CO₂ ~20× more soluble than O₂.","topic":"Gas exchange","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-respiration:e7","text":"Surfactant (type II pneumocytes) prevents collapse; absent → hyaline membrane disease.","topic":"Mechanics and surfactant","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-respiration:e8","text":"O₂ ≈ 98% on haemoglobin; CO₂ mainly as bicarbonate.","topic":"Gas transport in blood","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"14mm1hv":"a","y1tght":"a","1bvixmx":"a","18drdeq":"a","1bjtag":"a","1k4clhq":"a","1e34eiq":"a","1khuy3s":"a","5aant6":"a","1bjuk9l":"a","9n1191":"a"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-respiration:e0":{"s":0,"u":["Five processes: ventilation, lung exchange, blood transport, tissue exchange, mitochondrial oxidation.","Respiration supplies O₂ and removes CO₂ through five processes: pulmonary ventilation, gas exchange in the lungs, gas transport in the blood, gas exchange in the tissues, and mitochondrial oxidation."],"dp":[]},"physics1-respiration:e1":{"s":0,"u":["Conduction zone vs respiratory zone.","The airways form a conduction zone (upper airways to terminal bronchioles: warming, filtering, humidifying) and a respiratory zone (lobules: respiratory bronchioles, alveolar ducts, alveoli)."],"dp":[]},"physics1-respiration:e2":{"s":0,"u":["Inspiration active; expiration passive.","Inspiration is active (muscle contraction); expiration is passive and slightly slower."],"dp":[]},"physics1-respiration:e3":{"s":1,"u":["Gases diffuse down partial pressure gradients.","Gases always diffuse from higher to lower partial pressure .","CO₂ is about 20× more soluble than O₂, so it diffuses much more easily despite its small gradient; thickened membranes (fibrosis, oedema) impair O₂ first."],"dp":[]},"physics1-respiration:e4":{"s":1,"u":["Atmosphere PO₂ 152; alveolus PO₂ ≈ 100, PCO₂ 40; venous PO₂ 40, PCO₂ 47 mmHg.","Ventilation renews alveolar air: atmospheric PO₂ ≈ 152 mmHg , PCO₂ ≈ 0.2 mmHg; alveolar PO₂ ≈ 100-103 , PCO₂ ≈ 40 .","Capillary blood arrives with PO₂ ≈ 40 and PCO₂ ≈ 47 , so O₂ enters and CO₂ leaves."],"dp":[]},"physics1-respiration:e5":{"s":1,"u":["Fick: flux ∝ D·s·S·ΔP / e.","Alveolar-capillary diffusion (Fick): flux ∝ diffusion coefficient × solubility × surface S × partial pressure difference / membrane thickness e ."],"dp":[]},"physics1-respiration:e6":{"s":1,"u":["CO₂ ~20× more soluble than O₂.","CO₂ is about 20× more soluble than O₂, so it diffuses much more easily despite its small gradient; thickened membranes (fibrosis, oedema) impair O₂ first."],"dp":[]},"physics1-respiration:e7":{"s":2,"u":["Surfactant (type II pneumocytes) prevents collapse; absent → hyaline membrane disease.","By Laplace's law (P = 2T/r for a sphere), small alveoli with the same surface tension would collapse into larger ones; surfactant from type II pneumocytes lowers surface tension, prevents alveolar collapse at end-expiration and allows newborn lungs to open.","Its absence in premature babies causes hyaline membrane disease (respiratory distress)."],"dp":[{"h":"Why small alveoli need surfactant","t":"By Laplace's law, the pressure needed to keep a bubble open is proportional to surface tension and inversely to radius. Without surfactant, small alveoli would have higher internal pressure than large ones, empty into them and collapse. Surfactant lowers surface tension more as alveoli shrink, stabilising them; premature babies lacking it cannot keep their alveoli open. Source: the lecture's surfactant and alveolar-capillary barrier slides."}]},"physics1-respiration:e8":{"s":3,"u":["O₂ ≈ 98% on haemoglobin; CO₂ mainly as bicarbonate.","O₂ travels mainly bound to haemoglobin (about 98%), with a small dissolved fraction (proportional to PO₂).","CO₂ travels mostly as bicarbonate (about 70%, via carbonic anhydrase in red cells), as carbamino compounds bound to haemoglobin (about 20%), and dissolved (about 7-10%)."],"dp":[]}},"meta":{"14mm1hv":{"a":"recall","vg":"physics1-respiration:e2/recall/1"},"y1tght":{"a":"recall","vg":"physics1-respiration:e1/recall/1"},"1bvixmx":{"a":"recall","vg":"physics1-respiration:e4/recall/1"},"18drdeq":{"a":"recall","vg":"physics1-respiration:e4/recall/1"},"1bjtag":{"a":"recall","vg":"physics1-respiration:e3/recall/1"},"1k4clhq":{"a":"recall","vg":"physics1-respiration:e6/recall/1"},"1e34eiq":{"a":"recall","vg":"physics1-respiration:e5/recall/1"},"1khuy3s":{"a":"recall","vg":"physics1-respiration:e7/recall/1"},"5aant6":{"a":"recall","vg":"physics1-respiration:e7/recall/2"},"1bjuk9l":{"a":"recall","vg":"physics1-respiration:e8/recall/1"},"9n1191":{"a":"recall","vg":"physics1-respiration:e8/recall/1"}},"explRev":"b2a55e421329"};
